  T = `Páginas de eventos de promoción de ofertas`,
  E = `Aquí puedes encontrar las páginas de ofertas en Steam que presentan uno o más de tus juegos sobre los que tienes derechos de gestión. En algunos casos, estas páginas las organiza Valve como parte de sus eventos promocionales y, otras veces, lo hacen los organizadores del evento.`,
  D = `Estas son todas las páginas de rebajas activas y preparadas creadas por Valve o por una tercera parte autorizada. Para configurar que un nuevo asociado pueda crear su propia página de ofertas, %1$s. Puedes reenviar a tu asociado %2$s.`,
