  ws = `Proporciona una traducción al «Chino simplificado (Steam China)» para hacer que estas notas aparezcan en Steam China`,
  Ts = `Estas notas de parche también se publicarán en Steam China usando el texto de «Chino simplificado (Steam China)».`,
  Es = `Introducir notas de parche (por ejemplo, una lista de viñetas de cambios en la compilación que acabas de lanzar)`,
