  lE = `Tu precio actual es inferior a lo que normalmente se permitiría en esta moneda. Puedes dejarlo así, pero, si quieres rebajar tu juego, tendrás que ofrecer descuentos más bajos para que el precio descontado no sea inferior a la cantidad mínima por transacción permitida.`,
  uE = `«%1$s»: el precio en %2$s de %3$s es inferior al mínimo en %2$s de %4$s. Comprueba si hay algún error tipográfico (como un dígito que falte) e introduce %4$s o más.`,
  dE = `«%1$s»: el precio en %2$s de %3$s supera el publicado actualmente de %4$s. Como no es posible aumentar el precio de una suscripción recurrente, introduce %4$s o menos, o ponte en contacto con Steam si necesitas aumentarlo.`,
