  _E = `Según el método de conversión que has seleccionado y el precio en USD, el precio introducido es mucho más bajo que el recomendado (%1$s). Con este precio, el descuento máximo aplicable será del %2$s\xA0% para que el precio con descuento esté siempre por encima de 0,49\xA0USD.`,
