  jO = `No debe incluirse texto adicional (por ejemplo, «Ofertas del editor», «Fin de semana gratis» o «Hasta un 90\xA0% de descuento»), ya que el contexto se incluirá en el banner localizado que se superpone a este recurso. La única excepción es el texto «Ofertas de la franquicia».`,
