  UO = `Material gráfico: para obtener los mejores resultados, usa material gráfico que represente el nuevo contenido de la actualización, como nuevas ilustraciones clave, capturas de pantalla, nuevos personajes y características, etc.`,
  WO = `Logotipo: puede ser el logotipo del título principal del juego o un logotipo oficial de la actualización del juego, si corresponde. Si existen versiones del logotipo en varios idiomas para los recursos localizados, proporciónalas.`,
