  Bj = `Primera fecha de lanzamiento posible: %1$s`,
  Vj = `La primera fecha de lanzamiento posible es dos semanas después de que tu página de la tienda aparezca como «Próximamente» o 21\xA0días después de la primera compra de un crédito de aplicación (lo que ocurra más tarde). Tenlo en cuenta al planificar.`,
  Hj = `La primera fecha de lanzamiento posible es dos semanas después de que tu página de la tienda aparezca como «Próximamente». Tenlo en cuenta al planificar.`,
  Uj = `Selecciona la fecha en la que tienes previsto lanzar tu aplicación en Steam. Si aún falta mucho tiempo para el lanzamiento, introduce la fecha más aproximada que puedas. Si necesitas retrasar el lanzamiento, tendrás que actualizar la fecha aquí con al menos dos semanas de antelación a la fecha especificada anteriormente.`,
  Wj = `No es posible hacer lanzamientos durante los fines de semana, ya que Valve no está disponible para ayudar con los problemas que puedan surgir.`,
  Gj = `Todas las horas se refieren a la zona horaria del Pacífico.`,
  Kj = `Tu fecha de lanzamiento prevista se ha establecido para el %1$s. Si necesitas modificar esta fecha, <1>ponte en contacto con Valve desde aquí</1> con el motivo de tu nueva fecha de lanzamiento e indica qué fecha prefieres. Debes estar muy seguro de que el lanzamiento tendrá lugar en esta nueva fecha.`,
  qj = `NOTA: Al estar activa tu página «Próximamente», el cambio de la fecha de lanzamiento dará lugar a la publicación inmediata de tu página de la tienda para reflejar la fecha actualizada. Los cambios pendientes de la página de la tienda se harán públicos.`,
  Jj = `NOTA: La primera fecha de lanzamiento posible que puedes seleccionar es el %1$s. Puedes pulsar el botón de lanzamiento en cualquier momento después de esta fecha, independientemente de cuándo esté establecida la fecha de lanzamiento prevista.`,
