  dM = `Correos electrónicos de listas de deseados de demos`,
  fM = `Opción disponible durante 14\xA0días después del lanzamiento`,
  pM = `Ver la documentación de las listas de deseados`,
  mM = `Cuando lances tu demo por primera vez, tienes la opción de hacer que Steam mande una notificación a quienes tengan tu juego completo en su lista de deseados. Esta opción está disponible una vez dentro de las dos primeras semanas tras el lanzamiento de la demo. No puedes enviar dos notificaciones de listas de deseados con menos de dos semanas de diferencia, por lo que si tienes previsto lanzar tu juego en el plazo de dos semanas, quizá no te interese hacer esto.`,
  hM = `Está previsto que el juego base se lance el %1$s, dentro de un plazo de dos semanas desde este momento. Si envías correos de listas de deseados ahora, esas personas no los recibirán cuando se lance el juego.`,
  gM = `Enviaste correos de listas de deseados el %1$s. Puede que lleve algún tiempo enviar los correos a todas las personas que tienen tu juego en su lista de deseados.`,
  _M = `Ver estadísticas de listas de deseados`,
  vM = `(Este aviso desaparecerá después del %1$s).`,
  yM = `Notificar a los interesados`,
  bM = `¡Se han enviado los correos de listas de deseados!`,
  xM = `Ha habido un problema al intentar enviar los correos de las listas de deseados. Inténtalo de nuevo más tarde.`,
  SM = `Ha habido un problema al intentar recuperar la información sobre tu demo. Vuelve a intentarlo más tarde.`,
  CM = `El juego base y la demo tienen diferentes tipos de restricciones regionales. Ambos deben figurar en una lista de países permitidos o en una de denegados, pero no uno en cada una. Juego base: %1$s. Demo: %2$s.`,
  wM = `El juego base y la demo tienen diferentes restricciones regionales. Los correos electrónicos de la lista de deseados solo se enviarán a los clientes que puedan acceder a ambos. Juego base: %1$s. Demo: %2$s.`,
  TM = `solo disponible en %1$s`,
  EM = `no disponible en %1$s`,
  DM = `sin restricciones`,
  OM = `Atención, tu demo aún no aparece en la tienda:`,
  kM = `Accede a <1>Editar página de la tienda\xA0> Ajustes especiales\xA0> Demos asociadas</1> para asociar la demo con el juego base, y no olvides publicar los cambios. Las actualizaciones pueden tardar unos minutos en reconocerse tras completar esos pasos.`,
  AM = `¿Quieres avisar por correo electrónico del lanzamiento de la demo a quienes tienen tu juego en su lista de deseados?`,
  jM = `¿Quieres avisar por correo electrónico del lanzamiento de la demo a las personas que tienen tu juego en su lista de deseados?`,
  MM = `Limitaciones importantes`,
  NM = `<1><2>Solo se puede enviar un correo electrónico para avisar del lanzamiento de la demo.</2> Aunque desactives y vuelvas a activar la demo en el futuro, podrás enviar notificaciones por correo electrónico una sola vez.</1><1><2>Cada jugador solo recibirá un correo electrónico de Steam en un período de dos semanas.</2> Si lanzas el juego completo antes de que transcurran dos semanas tras enviar este correo, Steam no avisará por correo electrónico a ninguna de las personas a las que se notifique ahora. Ten esto en cuenta para trazar tus planes.</1>`,
  PM = `Enviar correos electrónicos`,
  FM = `Cancelar`,
  IM = `Si la fecha de lanzamiento de tu título se aproxima, puedes usar este ajuste para elegir cómo aparecerá el lanzamiento previsto en la tienda.`,
