  UM = `Asistente de compatibilidad con mandos`,
  WM = `Información sobre la compatibilidad con mandos`,
  GM = `Para describir lo mejor posible a los jugadores el nivel de compatibilidad con mandos que ofrece tu juego, tenemos un asistente rápido con unas cuantas preguntas cortas.

Responde a las preguntas del asistente de configuración lo mejor que puedas para que Steam pueda sugerir a los jugadores juegos que funcionan bien con los dispositivos que tienen.`,
  KM = `Estado: el asistente no se ha iniciado`,
  qM = `Estado: sin compatibilidad con mandos`,
  JM = `Iniciar el asistente`,
  YM = `Según lo que nos has contado acerca de la compatibilidad con mandos que ofrece tu juego, Steam mostrará a los usuarios el siguiente desglose:`,
