  KF = `Ten en cuenta que los requisitos del sistema deben describir todos los dispositivos de RV compatibles con tu juego, incluidos los de entrada. La compatibilidad con mandos indicada en esta sección debe referirse a los modos Escritorio y Big\xA0Picture.`,
