  sI = `Compatibilidad con mandos de Xbox`,
  cI = `Si tu juego ofrece compatibilidad total con mandos de Xbox, esto significa que los jugadores pueden iniciar, configurar, jugar y salir de tu juego sin necesidad de un teclado. Podrás indicar que tu juego es realmente compatible con mandos de Xbox si se cumplen los siguientes requisitos:`,
