  _I = `Se debe poder jugar, interactuar con los menús, cambiar los ajustes y salir del juego correctamente.`,
  vI = `<1>Nota sobre la utilización de USB o Bluetooth:</1> Es bastante normal que los mandos de PlayStation en un ordenador funcionen bien mediante una conexión USB pero no ofrezcan el mismo nivel de compatibilidad cuando se conecten mediante Bluetooth. Confirma con tu equipo técnico si tu juego funciona realmente bien con Bluetooth antes de marcarlo a continuación.`,
