  Xz = `Encuesta sobre reuniones de la industria con el equipo de Steam`,
  Zz = `Hola, %1$s:%2$s¿Dónde te gustaría reunirte con nosotros?`,
  Qz = `Puedes ver más abajo una lista de eventos a los que se están planteando asistir miembros del equipo de Steam. Si tú también te lo estás planteando o si vives cerca y estarás disponible para reunirnos, usa el formulario de más abajo para indicárnoslo. Utilizaremos esta información para planificar mejor nuestros viajes y eventos. Daremos prioridad a quienes van a asistir a los eventos a los que tenemos previsto ir antes de enviar invitaciones más generales.`,
