  yB = `Encuesta sobre Meet\xA0Steam: %1$s`,
  bB = `¿Tienes algún comentario sobre alguna de las sesiones de Steam a las que asististe en el espacio alquilado por Valve en Convene? Se trata literalmente de una encuesta de una sola pregunta. Únicamente queremos saber si algo te llamó la atención en cuanto al contenido, la calidad, las fechas, la ubicación o la temática de las sesiones, ya sea para bien o para mal.`,
