  VB = `Todos los vídeos de inicio contienen audio además de vídeo. El audio debería diseñarse para complementar la salida de los pequeños altavoces de Steam\xA0Deck y no sonar tan alto como para abrumar al usuario al iniciar el dispositivo.`,
  HB = `Los archivos de audio deben tener un formato de 16\xA0bits y una frecuencia de muestreo de 48\xA0kHz.`,
  UB = `La salida final debe tener un nivel de pico de -12\xA0dB y un volumen medio de -14\xA0LUFS. Normalizaremos el audio para asegurarnos de que no esté demasiado alto.`,
  WB = `Evita que haya demasiadas frecuencias medias-bajas y considera aplicar un filtro paso alto (HPF) a partir de 40-80\xA0Hz.`,
  GB = `Considera la posibilidad de añadir efectos de desvanecimiento al principio y al final del archivo de audio para evitar chasquidos o cortes bruscos al final del vídeo de inicio.`,
  KB = `Directrices para la imagen de previsualización`,
  qB = `Proporciona una imagen fija de tu vídeo de inicio con unas dimensiones de 1920\xA0×\xA01200\xA0píxeles. Dicha imagen se usará para representar tu vídeo de inicio en el inventario de los usuarios.`,
  JB = `Se aceptan los formatos\xA0JPEG, PNG y WEBP.`,
  YB = `No se permite el uso de capas de transparencia.`,
  XB = `No se permite el uso de animaciones. La imagen debe contener un solo fotograma.`,
  ZB = `Vinculado a %1$s`,
  QB = `Este nombre no se puede modificar mientras esté vinculado a la página de un creador. Si es necesario editarlo, desvincúlalo primero.`,
  $B = `Desvincular «%1$s» de «%2$s» para este juego. Esto se aplicará inmediatamente.`,
