  tV = `Tu página de franquicia no puede ser la misma que tu página de desarrollador o editor.`,
  nV = `Este grupo ya está vinculado a un editor con un nombre diferente. Consulta las instrucciones de la derecha.`,
  rV = `Este grupo está vinculado como desarrollador o editor en otra aplicación, por lo que la tienda no lo mostrará como franquicia. En su lugar, vincula un grupo que se utilice solo para la franquicia.`,
  iV = `Vinculada como desarrollador o editor en:`,
  aV = `(%1$s\xA0más)`,
  oV = `La tienda vincula una franquicia a su página principal cuando al menos dos juegos de la tienda la tienen asignada como franquicia. Los DLC, las demos y el software no cuentan. Hasta entonces, el nombre de la franquicia se muestra sin enlace.`,
  sV = `Elige una página de creador`,
  cV = `Vincular «%1$s» a una página principal`,
