  dV = `*\xA0Indica que esta página de creador ya está vinculada a otro juego de tu cuenta de asociado.`,
  fV = `No se pudo determinar la cuenta de asociado de este juego, por lo que aquí no se ofrecen las páginas de creador vinculadas a tus otros juegos. Solo se muestran los grupos de la comunidad de los que eres propietario u oficial.`,
  pV = `No hay ninguna página de creador o grupo de la comunidad disponible para vincular. Debes ser propietario u oficial del grupo de la comunidad, o el grupo ya debe estar vinculado a otro juego de tu cuenta de asociado.`,
