  VU = `Define y actualiza los logros de tu juego.`,
  HU = `Para un resultado óptimo, los iconos de los logros deberían ser imágenes PNG de 256\xA0×\xA0256\xA0píxeles. El tamaño mínimo admitido es de 64\xA0×\xA064\xA0píxeles, pero es aconsejable utilizar el más grande. Recomendamos que los iconos de los logros desbloqueados sean coloridos; los de los bloqueados deben estar en escala de grises.`,
  UU = `Debido a que los logros pueden aparecer en diferentes lugares de la comunidad de Steam, los nombres e iconos que introduzcas deben ser apropiados para todas las edades y públicos. Valve puede eliminar juegos de la tienda por completo si sus logros infringen las <1>directrices sobre contenido de la comunidad</1> o son ofensivos.`,
